/**
 * errors.mjs — error types raised by the AES core.
 *
 * The Python original raises bare `ValueError`s from inside `pyaes`
 * (`ValueError: Invalid key size`, `ValueError: plaintext block must be
 * 16 bytes`). This layer stays deliberately Python-agnostic: it knows nothing
 * about tracebacks, exit codes or `repr()`. The pyaes shim sitting above it is
 * responsible for translating these classes into the exact CPython-style
 * diagnostics, so the cipher core remains a clean, reusable library.
 */

/**
 * Raised when a key is not 16, 24 or 32 bytes long.
 *
 * The default message matches the text the Python side ultimately reports, but
 * callers may override it.
 */
export class InvalidKeySizeError extends Error {
  /** @param {string} [message] */
  constructor(message = 'Invalid key size') {
    super(message);
    this.name = 'InvalidKeySizeError';
  }
}

/**
 * Raised when a block handed to the cipher is not exactly `BLOCK_SIZE` bytes.
 *
 * The message is always supplied by the caller, because the wording differs by
 * direction upstream (plaintext vs. ciphertext block).
 */
export class InvalidBlockSizeError extends Error {
  /** @param {string} message */
