/**
 * galois.mjs — arithmetic in the finite field GF(2^8) used by AES.
 *
 * The Python original (`pyaes`) ships pre-computed S-box / multiplication
 * tables. This port reproduces the *values* of those tables by deriving them
 * from first principles (FIPS-197 §4), so the only thing hard-coded anywhere in
 * the AES core is the field's reduction polynomial. Nothing here touches
 * `node:crypto`; every operation is plain integer bit math on bytes.
 *
 * Field: GF(2) polynomials modulo the irreducible AES polynomial
 *   m(x) = x^8 + x^4 + x^3 + x + 1   (0x11b)
 *
 * Bytes are ordinary JS numbers in the range 0..255.
 */

/** The AES reduction polynomial, minus its x^8 term (FIPS-197 §4.2). */
const REDUCTION = 0x1b;

/**
 * Multiply a byte by x (i.e. by 0x02) in GF(2^8).
 *
 * A left shift is the polynomial multiplication; if the shift pushed a bit out
 * of the x^7 position the result is reduced modulo m(x) by XORing 0x1b.
 *
 * @param {number} a byte, 0..255
 * @returns {number} byte, 0..255
 */
export function xtime(a) {
  const b = (a & 0xff) << 1;
  return (b & 0x100 ? b ^ REDUCTION : b) & 0xff;
}

/**
 * Multiply two bytes in GF(2^8) (russian-peasant / shift-and-add).
 *
 * Runs in constant iteration count (8) so it stays trivially auditable; it is
 * only ever used at module-load time to build the lookup tables.
 *
 * @param {number} a byte, 0..255
 * @param {number} b byte, 0..255
 * @returns {number} byte, 0..255
 */
export function gmul(a, b) {
  let x = a & 0xff;
  let y = b & 0xff;
  let product = 0;
  for (let i = 0; i < 8; i += 1) {
    if (y & 1) product ^= x;
    y >>= 1;
    x = xtime(x);
  }
  return product & 0xff;
}

/**
 * Multiplicative inverse in GF(2^8).
 *
 * Zero has no inverse; AES defines the S-box so that 0x00 maps to itself, so we
 * follow that convention and return 0 for 0 (FIPS-197 §5.1.1).
 *
 * The table is built once at module load by exhaustive search over the 255
 * non-zero field elements — small, deterministic, and free of any dependency on
 * a hard-coded inverse table.
 *
 * @param {number} a byte, 0..255
 * @returns {number} byte, 0..255
 */
export function ginv(a) {
  return INVERSES[a & 0xff];
}

/** Lazily-free precomputation: 256-entry inverse table, index 0 fixed at 0. */
const INVERSES = (() => {
  const table = new Uint8Array(256);
  for (let a = 1; a < 256; a += 1) {
    if (table[a] !== 0) continue; // already filled in as some earlier pair
    for (let b = 1; b < 256; b += 1) {
      if (gmul(a, b) === 1) {
        table[a] = b;
        table[b] = a; // inversion is an involution
        break;
      }
    }
  }
  return table;
})();
===== /output/lib/aes/key-schedule.mjs
/**
 * key-schedule.mjs — the AES key expansion (FIPS-197 §5.2).
 *
 * Mirrors what `pyaes.AES.__init__` does when it is handed a key: reject
 * anything that is not 16/24/32 bytes (`ValueError: Invalid key size` upstream),
 * otherwise expand the key into `rounds + 1` round keys.
 *
 * Byte order note: `pyaes` keeps its round keys as 32-bit words and transposes
 * during AddRoundKey. Here each round key is flattened into a Uint8Array(16)
 * whose byte order is identical to the 16-byte input block, so AddRoundKey is a
 * plain 16-way XOR with no transposition anywhere in the hot path.
 */

import { SBOX, RCON } from './tables.mjs';
import { InvalidKeySizeError } from './errors.mjs';

/** AES block size in bytes. Always 16 — Rijndael's larger blocks are not AES. */
export const BLOCK_SIZE = 16;

/**
 * Number of rounds per key length in bytes (FIPS-197 Fig. 4).
 * @type {Map<number, number>}
 */
export const ROUNDS_BY_KEY_SIZE = new Map([
  [16, 10],
  [24, 12],
  [32, 14],
]);

/**
 * True when `byteLength` is a key size AES accepts.
 * @param {number} byteLength
 * @returns {boolean}
 */
export function isValidKeySize(byteLength) {
  return ROUNDS_BY_KEY_SIZE.has(byteLength);
}

/**
 * Apply the S-box to each byte of a 4-byte word, in place.
 * @param {Uint8Array} word
 */
function subWord(word) {
  word[0] = SBOX[word[0]];
  word[1] = SBOX[word[1]];
  word[2] = SBOX[word[2]];
  word[3] = SBOX[word[3]];
}

/**
 * Rotate a 4-byte word one byte left: [a0,a1,a2,a3] -> [a1,a2,a3,a0].
 * @param {Uint8Array} word
 */
function rotWord(word) {
  const first = word[0];
  word[0] = word[1];
  word[1] = word[2];
  word[2] = word[3];
  word[3] = first;
}

/**
 * Expand a cipher key into the AES round keys.
 *
 * @param {Uint8Array} keyBytes 16, 24 or 32 bytes
 * @returns {{ keySize: number, rounds: number, roundKeys: Uint8Array[] }}
 *   `roundKeys` has `rounds + 1` entries, each a fresh Uint8Array(16) in input
 *   block byte order.
 * @throws {InvalidKeySizeError} when the key length is not 16/24/32
 */
export function expandKey(keyBytes) {
  const keySize = keyBytes == null ? -1 : keyBytes.length;
  if (!isValidKeySize(keySize)) throw new InvalidKeySizeError();

  const rounds = /** @type {number} */ (ROUNDS_BY_KEY_SIZE.get(keySize));
  const nk = keySize / 4; // key length in 32-bit words: 4, 6 or 8
  const totalWords = 4 * (rounds + 1); // 44, 52 or 60

  // words[i] is w_i from FIPS-197, stored big-endian as 4 bytes.
  /** @type {Uint8Array[]} */
  const words = new Array(totalWords);

  for (let i = 0; i < nk; i += 1) {
    words[i] = Uint8Array.prototype.slice.call(keyBytes, i * 4, i * 4 + 4);
  }

  for (let i = nk; i < totalWords; i += 1) {
    const temp = words[i - 1].slice();
    if (i % nk === 0) {
      rotWord(temp);
      subWord(temp);
      temp[0] ^= RCON[i / nk];
    } else if (nk > 6 && i % nk === 4) {
      // AES-256 only: an extra SubWord halfway through each key block.
      subWord(temp);
    }
    const prev = words[i - nk];
    const word = new Uint8Array(4);
    word[0] = prev[0] ^ temp[0];
    word[1] = prev[1] ^ temp[1];
    word[2] = prev[2] ^ temp[2];
    word[3] = prev[3] ^ temp[3];
    words[i] = word;
  }

  // Flatten groups of four words into block-ordered 16-byte round keys.
  /** @type {Uint8Array[]} */
  const roundKeys = new Array(rounds + 1);
  for (let r = 0; r <= rounds; r += 1) {
    const roundKey = new Uint8Array(BLOCK_SIZE);
    for (let w = 0; w < 4; w += 1) roundKey.set(words[r * 4 + w], w * 4);
    roundKeys[r] = roundKey;
  }

  return { keySize, rounds, roundKeys };
}
