/**
 * tables.mjs — the AES substitution boxes, round constants and MixColumns
 * multiplication tables, all derived at module load.
 *
 * `pyaes` carries these as literal Python lists. Reproducing the literals by
 * hand would be unverifiable, so instead the S-box is *computed* exactly as
 * FIPS-197 §5.1.1 defines it — multiplicative inverse in GF(2^8) followed by the
 * affine transform — and then checked against known FIPS-197 values. If the
 * derivation is ever wrong the module refuses to load rather than silently
 * producing wrong ciphertext.
 */

import { gmul, ginv, xtime } from './galois.mjs';

/**
 * Rotate a byte left by `n` bits (the `b_i xor b_(i+4) xor ...` shifts in the
 * S-box affine transform are byte rotations).
 *
 * @param {number} b byte, 0..255
 * @param {number} n bit count, 1..7
 * @returns {number} byte, 0..255
 */
function rotl8(b, n) {
  return ((b << n) | (b >>> (8 - n))) & 0xff;
}

/**
 * The AES S-box: y = affine(inv(x)).
 *
 * affine(b) = b ^ rotl(b,1) ^ rotl(b,2) ^ rotl(b,3) ^ rotl(b,4) ^ 0x63
 *
 * @type {Uint8Array}
 */
export const SBOX = (() => {
  const box = new Uint8Array(256);
  for (let x = 0; x < 256; x += 1) {
    const b = ginv(x);
    box[x] = (b ^ rotl8(b, 1) ^ rotl8(b, 2) ^ rotl8(b, 3) ^ rotl8(b, 4) ^ 0x63) & 0xff;
  }
  return box;
})();

/**
 * The inverse S-box, obtained by inverting the permutation above.
 * @type {Uint8Array}
 */
export const INV_SBOX = (() => {
  const box = new Uint8Array(256);
  for (let x = 0; x < 256; x += 1) box[SBOX[x]] = x;
  return box;
})();

/**
 * Round constants. `RCON[i]` (for i >= 1) is x^(i-1) in GF(2^8):
 * 01 02 04 08 10 20 40 80 1b 36. Index 0 is unused padding so that the array is
 * indexed by round number, matching FIPS-197's notation.
 * @type {Uint8Array}
 */
export const RCON = (() => {
  const rcon = new Uint8Array(11);
  let value = 0x01;
  for (let i = 1; i < 11; i += 1) {
    rcon[i] = value;
    value = xtime(value);
  }
  return rcon;
})();

/**
 * Build a 256-entry table of `byte -> gmul(byte, factor)`.
 * @param {number} factor
 * @returns {Uint8Array}
 */
function mulTable(factor) {
  const table = new Uint8Array(256);
  for (let x = 0; x < 256; x += 1) table[x] = gmul(x, factor);
  return table;
}

/** Multiply-by-2 table (MixColumns). @type {Uint8Array} */
export const MUL2 = mulTable(0x02);
/** Multiply-by-3 table (MixColumns). @type {Uint8Array} */
export const MUL3 = mulTable(0x03);
/** Multiply-by-9 table (InvMixColumns). @type {Uint8Array} */
